using Godot;
using Kairnfall.Core;

namespace Kairnfall.Client;

public partial class GameRoot
{
    private bool TutorialDone(Character player,string id)=>player.Tutorial.Contains(id)||
        (TutorialProgress.IsLocalHint(id)&&settings.GetValue("tutorial_"+player.Id,id,false).AsBool());
    private string TutorialText(string text)
    {
        foreach(var binding in bindings) text=text.Replace("{"+binding.Key+"}",binding.Value.ToString(),StringComparison.Ordinal);
        return text;
    }
    private void RecordTutorialView(string pageName)
    {
        if(Snapshot is not {} snapshot) return;
        string key=pageName switch {"Inventory"=>"inventory","Map"=>"map",_=>""};
        if(key==""||TutorialDone(snapshot.Self,key)) return;
        settings.SetValue("tutorial_"+snapshot.Self.Id,key,true); settings.Save("user://settings.cfg");
    }
    private void UpdateTutorialTracker(Character player)
    {
        if(!settings.GetValue("hud","tutorial_hints",true).AsBool()) return;
        var next=TutorialProgress.Lessons.FirstOrDefault(lesson=>!TutorialDone(player,lesson.Id));
        if(next is null) return;
        int complete=TutorialProgress.Lessons.Count(lesson=>TutorialDone(player,lesson.Id));
        objectiveText.Text=$"LEARNING {complete}/{TutorialProgress.Lessons.Count}\n{next.Title}\n"+TutorialText(next.Hint);
    }
    private void BuildTutorialPage()
    {
        if(page is null||Snapshot is null) return;
        page.AddChild(Ui.Label("Learn by playing",23,Ui.Gold));
        page.AddChild(Ui.Label("Gameplay milestones are saved on the server. Viewed hints are saved on this device for this character. No lesson grants developer items or forces a death.",14,Ui.Muted,true));
        bool hints=settings.GetValue("hud","tutorial_hints",true).AsBool();
        page.AddChild(Ui.Button(hints?"Hide tutorial tracker":"Show tutorial tracker",()=>
        {
            settings.SetValue("hud","tutorial_hints",!settings.GetValue("hud","tutorial_hints",true).AsBool());
            settings.Save("user://settings.cfg"); OpenPage("Guide");
        }));
        var rows=Ui.Column(Ui.Scroll(page,new Vector2(700,350)));
        string last="";
        void Render()
        {
            if(Snapshot is not {} snapshot) return;
            var player=snapshot.Self;
            string stamp=player.Id+string.Join("",TutorialProgress.Lessons.Select(lesson=>TutorialDone(player,lesson.Id)?"1":"0"));
            if(stamp==last) return; last=stamp; Ui.Clear(rows);
            var next=TutorialProgress.Lessons.FirstOrDefault(lesson=>!TutorialDone(player,lesson.Id));
            foreach(var lesson in TutorialProgress.Lessons)
            {
                bool done=TutorialDone(player,lesson.Id);
                var card=new PanelContainer(); rows.AddChild(card); var body=Ui.Column(card);
                body.AddChild(Ui.Label((done?"Done · ":next?.Id==lesson.Id?"Next · ":"")+lesson.Title,18,done?Ui.Success:Ui.Gold,true));
                body.AddChild(Ui.Label(TutorialText(lesson.Hint),15,Ui.Text,true));
                if(lesson.Id=="recovery")
                {
                    body.AddChild(Ui.Label("Death keeps your inventory and gold. Equipped items lose 10 durability points. Respawn becomes available after five seconds. An active companion is lost. Repair damaged equipment at a smith.",15,Ui.Text,true));
                    if(!done) body.AddChild(Ui.Button("I have read the recovery rules",()=>
                    {
                        if(Snapshot is null) return;
                        settings.SetValue("tutorial_"+Snapshot.Self.Id,"recovery",true); settings.Save("user://settings.cfg");
                        last=""; Render();
                    }));
                }
                else if(!done&&lesson.Page!="")
                {
                    string destination=lesson.Page; body.AddChild(Ui.Button("Open "+destination,()=>OpenPage(destination)));
                }
            }
        }
        refreshPage=Render; Render();
    }
}

using System.Text.Json;
using Kairnfall.Core;

public static class TutorialCases
{
    public static void Run(Action<string,Action> test,Catalog data)
    {
        void Check(bool value,string message) { if(!value) throw new InvalidOperationException(message); }
        (RealmEngine,Character) Fixture()
        {
            var realm=new RealmEngine(data); var player=realm.CreateCharacter("tutorial-account","Tutorial Fixture","vanguard",new());
            realm.Active.Add(player.Id); return (realm,player);
        }
        GameCommand Command(RealmEngine realm,Character player,string kind,string arg="",string item="",string target="")
            =>new(){Kind=kind,Arg=arg,Item=item,Target=target,Sequence=realm.Player(player.Id).LastAction+1};
        test("Tutorial milestones are empty for new and legacy characters",()=>
        {
            var (_,player)=Fixture(); Check(player.Tutorial.Count==0,"New character skipped tutorial.");
            var legacy=JsonSerializer.Deserialize<Character>("{}",Wire.Json)!; Check(legacy.Tutorial.Count==0,"Legacy defaults failed.");
            Check(TutorialProgress.Lessons.Select(x=>x.Id).Distinct().Count()==TutorialProgress.Lessons.Count,"Duplicate lessons.");
        });
        test("Rejected tutorial and movement commands cannot mark completion",()=>
        {
            var (realm,player)=Fixture();
            Check(!realm.Execute(player.Id,Command(realm,player,"tutorial_ack","equip")).Ok,"Forged acknowledgement accepted.");
            Check(!realm.Execute(player.Id,new GameCommand{Kind="move",X=200}).Ok,"Invalid movement accepted.");
            Check(realm.Player(player.Id).Tutorial.Count==0,"Rejected actions marked completion.");
        });
        test("Actual server movement records the first lesson",()=>
        {
            var (realm,player)=Fixture(); realm.Execute(player.Id,new GameCommand{Kind="move",Y=1}); realm.Tick(.05);
            Check(player.Tutorial.Contains("move"),"Actual displacement was not recorded.");
        });
        test("Equipment tutorial preserves validated commands and replay",()=>
        {
            var (realm,player)=Fixture(); string item=player.Equipment["weapon"]; long gold=player.Gold;
            Check(!realm.Execute(player.Id,Command(realm,player,"equip",item:"missing")).Ok,"Invalid equipment accepted.");
            player=realm.Player(player.Id); Check(!player.Tutorial.Contains("equip"),"Invalid equipment marked tutorial.");
            Check(realm.Execute(player.Id,Command(realm,player,"unequip","weapon")).Ok,"Unequip failed.");
            var command=Command(realm,player,"equip",item:item); Check(realm.Execute(player.Id,command).Ok,"Equip failed.");
            long sequence=player.LastAction; Check(realm.Execute(player.Id,command).Ok,"Replay failed.");
            Check(player.LastAction==sequence&&player.Tutorial.Contains("equip")&&player.Gold==gold,"Tutorial changed economy or replay.");
        });
        test("Tutorial milestones survive save roundtrip without crossing accounts",()=>
        {
            var (realm,player)=Fixture(); var other=realm.CreateCharacter("other-tutorial","Other Tutorial","ranger",new());
            TutorialProgress.Record(player,"talk"); var loaded=new RealmEngine(data,Wire.Copy(realm.State));
            Check(loaded.Player(player.Id).Tutorial.Contains("talk"),"Save lost tutorial.");
            Check(loaded.Player(other.Id).Tutorial.Count==0,"Tutorial crossed ownership.");
        });
        test("Door tutorial records valid entry and return but rejects remote doors",()=>
        {
            var (realm,player)=Fixture(); var entry=data.Zone(player.Zone).Exits.First(x=>data.Zone(x.Target).Kind=="interior");
            Check(!realm.Execute(player.Id,Command(realm,player,"transition",target:entry.Id)).Ok,"Remote door accepted.");
            player=realm.Player(player.Id); Check(!player.Tutorial.Contains("enter_building"),"Remote door marked tutorial.");
            player.Position=entry.Position; Check(realm.Execute(player.Id,Command(realm,player,"transition",target:entry.Id)).Ok,"Entry failed.");
            Check(player.Tutorial.Contains("enter_building"),"Entry not recorded.");
            var exit=data.Zone(player.Zone).Exits.First(x=>x.Target=="wayfarers_rest"); player.Position=exit.Position;
            Check(realm.Execute(player.Id,Command(realm,player,"transition",target:exit.Id)).Ok,"Return failed.");
            Check(player.Tutorial.Contains("exit_building"),"Return not recorded.");
        });
        test("Unknown saved tutorial milestones fail validation",()=>
        {
            var (realm,player)=Fixture(); player.Tutorial.Add("invented"); bool rejected=false;
            try { _=new RealmEngine(data,Wire.Copy(realm.State)); } catch(InvalidDataException) {rejected=true;}
            Check(rejected,"Unknown milestones accepted.");
        });
    }
}
